<?php// Start output buffering to prevent any accidental outputob_start();// Set error reportingerror_reporting(E_ALL);ini_set('display_errors', 0); // Don't display errors in JSON responsesession_start();// Clear any previous outputob_clean();require_once __DIR__ . '/access.php';header('Content-Type: application/json; charset=UTF-8');mb_internal_encoding('UTF-8');// Check if user has permission to uploadif (!isAdmin() && !isManager()) {    http_response_code(403);    echo json_encode(['success' => false, 'message' => 'Nemáte oprávnění k nahrávání souborů']);    exit;}if ($_SERVER['REQUEST_METHOD'] === 'POST') {    // Check for upload errors first    if (empty($_POST) && empty($_FILES) && $_SERVER['CONTENT_LENGTH'] > 0) {        echo json_encode(['success' => false, 'message' => 'Chunk je příliš velký pro server']);        exit;    }        $chunkIndex = intval($_POST['chunkIndex'] ?? 0);    $totalChunks = intval($_POST['totalChunks'] ?? 1);    $fileName = $_POST['fileName'] ?? '';    $targetFolder = $_POST['targetFolder'] ?? '';    $fileId = $_POST['fileId'] ?? '';        if (empty($fileName) || empty($targetFolder) || empty($fileId)) {        echo json_encode(['success' => false, 'message' => 'Chybí požadované parametry']);        exit;    }        // Validate chunk parameters    if ($chunkIndex < 0 || $chunkIndex >= $totalChunks || $totalChunks <= 0) {        echo json_encode(['success' => false, 'message' => 'Neplatné parametry chunků']);        exit;    }        // Sanitize parameters    $targetFolder = basename($targetFolder);    $fileName = basename($fileName);    $fileId = preg_replace('/[^a-zA-Z0-9]/', '', $fileId); // Only alphanumeric for safety        // Validate file extension    $fileExtension = strtolower(pathinfo($fileName, PATHINFO_EXTENSION));    $allowedExtensions = ['mp4', 'avi', 'mov', 'mkv', 'webm', 'mp3', 'wav', 'aac'];        if (!in_array($fileExtension, $allowedExtensions)) {        echo json_encode(['success' => false, 'message' => 'Nepodporovaný formát souboru']);        exit;    }        // Create temporary directory for chunks    $tempDir = __DIR__ . '/temp_uploads/';    if (!is_dir($tempDir)) {        if (!mkdir($tempDir, 0755, true)) {            echo json_encode(['success' => false, 'message' => 'Nepodařilo se vytvořit dočasný adresář']);            exit;        }    }        // Handle chunk upload    if (isset($_FILES['chunk'])) {        $chunk = $_FILES['chunk'];                // Check for upload errors        if ($chunk['error'] !== UPLOAD_ERR_OK) {            $errorMessage = 'Chyba při nahrávání chunk';            switch ($chunk['error']) {                case UPLOAD_ERR_INI_SIZE:                case UPLOAD_ERR_FORM_SIZE:                    $errorMessage = 'Chunk je příliš velký';                    break;                case UPLOAD_ERR_PARTIAL:                    $errorMessage = 'Chunk byl nahrán pouze částečně';                    break;            }            echo json_encode(['success' => false, 'message' => $errorMessage]);            exit;        }                $chunkFile = $tempDir . $fileId . '_chunk_' . $chunkIndex;                if (move_uploaded_file($chunk['tmp_name'], $chunkFile)) {            chmod($chunkFile, 0644);                        // Check if this is the last chunk            if ($chunkIndex === $totalChunks - 1) {                // Reassemble all chunks                $baseDir = getRoot('videos');                $targetDir = $baseDir . $targetFolder . '/';                                // Check if target folder exists                if (!is_dir($targetDir)) {                    // Clean up chunks                    for ($i = 0; $i <= $chunkIndex; $i++) {                        $chunkPath = $tempDir . $fileId . '_chunk_' . $i;                        if (file_exists($chunkPath)) {                            unlink($chunkPath);                        }                    }                    echo json_encode(['success' => false, 'message' => 'Cílová složka neexistuje']);                    exit;                }                                $finalFile = $targetDir . $fileName;                                // Handle duplicate filenames                $counter = 1;                $originalName = pathinfo($fileName, PATHINFO_FILENAME);                while (file_exists($finalFile)) {                    $fileName = $originalName . '_' . $counter . '.' . $fileExtension;                    $finalFile = $targetDir . $fileName;                    $counter++;                }                                // Combine all chunks                $finalFileHandle = fopen($finalFile, 'wb');                if ($finalFileHandle) {                    $success = true;                    $totalBytesWritten = 0;                                        for ($i = 0; $i < $totalChunks; $i++) {                        $chunkPath = $tempDir . $fileId . '_chunk_' . $i;                        if (file_exists($chunkPath)) {                            $chunkContent = file_get_contents($chunkPath);                            if ($chunkContent === false) {                                $success = false;                                error_log("Failed to read chunk $i for file $fileName");                                break;                            }                                                        $bytesWritten = fwrite($finalFileHandle, $chunkContent);                            if ($bytesWritten === false) {                                $success = false;                                error_log("Failed to write chunk $i for file $fileName");                                break;                            }                                                        $totalBytesWritten += $bytesWritten;                            unlink($chunkPath); // Clean up chunk                        } else {                            $success = false;                            error_log("Missing chunk $i for file $fileName");                            break;                        }                    }                    fclose($finalFileHandle);                                        if ($success) {                        chmod($finalFile, 0644);                                                // Verify file integrity                        $finalSize = filesize($finalFile);                                                // For video files, do a quick verification that the file seems valid                        $isValidFile = true;                        if (in_array($fileExtension, ['mp4', 'avi', 'mov', 'mkv', 'webm'])) {                            // Basic check - file should be larger than 1KB and readable                            if ($finalSize < 1024) {                                $isValidFile = false;                                error_log("Assembled video file $fileName seems too small: $finalSize bytes");                            }                        }                                                if ($isValidFile) {                            error_log("Successfully assembled file $fileName: $finalSize bytes");                            echo json_encode([                                'success' => true,                                 'message' => 'Soubor byl úspěšně nahrán',                                'fileName' => $fileName,                                'fileSize' => $finalSize,                                'isComplete' => true                            ]);                        } else {                            // Clean up invalid file                            if (file_exists($finalFile)) {                                unlink($finalFile);                            }                            echo json_encode(['success' => false, 'message' => 'Sestavený soubor se zdá být poškozený']);                        }                    } else {                        // Clean up incomplete file                        if (file_exists($finalFile)) {                            unlink($finalFile);                        }                        echo json_encode(['success' => false, 'message' => 'Chyba při sestavování souboru - některé části chybí']);                    }                } else {                    echo json_encode(['success' => false, 'message' => 'Nepodařilo se vytvořit finální soubor - zkontrolujte oprávnění']);                }            } else {                // Chunk uploaded successfully, waiting for more                echo json_encode([                    'success' => true,                     'message' => 'Chunk nahrán',                    'chunkIndex' => $chunkIndex,                    'isComplete' => false                ]);            }        } else {            echo json_encode(['success' => false, 'message' => 'Nepodařilo se uložit chunk']);        }    } else {        echo json_encode(['success' => false, 'message' => 'Nebyl nalezen chunk']);    }} else {    echo json_encode(['success' => false, 'message' => 'Neplatná metoda požadavku']);}exit;?>